using Microsoft.EntityFrameworkCore;
class BlogContext : DbContext
{
    public DbSet<Blog> Blogs => Set<Blog>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // Breaking change 1: EF9 renamed the discriminator property from
        // "Discriminator" to "$type". Existing documents still use the old name,
        // so pin the property name to keep reading them.
        modelBuilder.Entity<Blog>().HasDiscriminator<string>("Discriminator");

        // Breaking change 2: EF9 changed the id format from "EntityType|Key"
        // to just "Key". Existing documents use "Blog|1", so preserve the
        // old id factory to keep reading/writing them correctly.
        modelBuilder.Entity<Blog>().HasPartitionKey(b => b.Id);
        modelBuilder.Entity<Blog>().Property(b => b.Id)
            .HasJsonPropertyName("id")
            .ToJsonProperty("id");

        // Breaking change 3: HasIndex() now throws at model validation for the
        // Cosmos provider. Cosmos manages indexing via its own index policy, not
        // through EF Core, so this call must be removed.
        // (was: modelBuilder.Entity<Blog>().HasIndex(b => b.Name);)
    }
}
class Blog { public string Id { get; set; } public string Name { get; set; } }

