class SyncJob
{
    void Run(BlogContext context)
    {
        // Breaking change 4: EF9 uses sync-over-async for Cosmos operations.
        // SaveChanges() now throws InvalidOperationException if called from a
        // thread-pool thread without a SynchronizationContext. Prefer async.
        var blogs = context.Blogs.ToList();
        foreach (var b in blogs) { b.Name = b.Name.Trim(); }
        context.SaveChanges();
    }

    // Preferred async version to avoid sync-over-async issues:
    async Task RunAsync(BlogContext context)
    {
        var blogs = await context.Blogs.ToListAsync();
        foreach (var b in blogs) { b.Name = b.Name.Trim(); }
        await context.SaveChangesAsync();
    }
}

